import "server-only";

import { projects } from "@/lib/api";
import { must } from "@/lib/backend";
import type { Project, Task } from "@/lib/types";

export type ProjectCardProps = {
    project: Pick<Project, "id" | "name" | "summary">;
};

export async function readProjectCard(project: Project): Promise<ProjectCardProps> {
    return {
        project: {
            id: project.id,
            name: project.name,
            summary: project.summary,
        },
    };
}

export type ProjectViewProps = {
    project: Pick<Project, "id" | "name" | "summary"> & {
        tasks: Pick<Task, "id" | "title">[];
    };
};

export async function readProjectView(project: Project): Promise<ProjectViewProps> {
    const [tasks] = await Promise.all([
        must(projects.tasks(project.id)),
    ]);
    return {
        project: {
            id: project.id,
            name: project.name,
            summary: project.summary,
            tasks: tasks.map((item) => ({ id: item.id, title: item.title })),
        },
    };
}

export type TaskViewProps = {
    task: Pick<Task, "id" | "title" | "status" | "due" | "finished_at"> & {
        project: Pick<Project, "id" | "name">;
    };
};

export async function readTaskView(task: Task): Promise<TaskViewProps> {
    const [project] = await Promise.all([
        must(projects.get(task.project_id)),
    ]);
    return {
        task: {
            id: task.id,
            title: task.title,
            status: task.status,
            due: task.due,
            finished_at: task.finished_at,
            project: { id: project.id, name: project.name },
        },
    };
}
